-- Clean staging database only. Production already has these baseline tables.
CREATE TABLE customers(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE licenses(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),product TEXT NOT NULL DEFAULT 'GrainsDosage',license_hash TEXT NOT NULL UNIQUE,gumroad_sale_id TEXT UNIQUE,max_devices INTEGER NOT NULL DEFAULT 2 CHECK(max_devices=2),replacements_allowed INTEGER NOT NULL DEFAULT 1 CHECK(replacements_allowed=1),replacements_used INTEGER NOT NULL DEFAULT 0 CHECK(replacements_used BETWEEN 0 AND 1),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked','refunded')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activations(id TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES licenses(id),machine_id_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')),activated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TEXT,last_seen_at TEXT,UNIQUE(license_id,machine_id_hash));
CREATE TABLE license_events(id TEXT PRIMARY KEY,license_id TEXT REFERENCES licenses(id),event_type TEXT NOT NULL,machine_id_hash TEXT,metadata_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE license_policy(product TEXT PRIMARY KEY,max_devices INTEGER NOT NULL,max_replacements INTEGER NOT NULL,validity_days INTEGER NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,license_duration_days INTEGER NOT NULL DEFAULT 365,require_key_reentry INTEGER NOT NULL DEFAULT 1,allowed_major_version INTEGER NOT NULL DEFAULT 1,is_perpetual INTEGER NOT NULL DEFAULT 0);
